def describe_universal_autonomous_civilization() -> str:
    lines = [
        "TitanAI Universal Autonomous Civilization Era",
        "",
        "This era represents the transition from a global intelligence network into a unified digital civilization operating framework.",
        "",
    ]
    for capability in CIVILIZATION_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.domain}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
